(()=>{
'use strict';
const $=s=>document.querySelector(s),cloud=window.ChiLeMeCloud;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sort='new',offset=0,feed=[],leaders=[],authMode='login',verificationEmail='',pendingPassword='',pendingUsername='',profile=null,previewURL='',loading=false,activePost=null;
const date=s=>new Date(s).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});
function notice(s){$('#social-status').textContent=s;$('#social-status').hidden=!s;}
function avatar(path,name){const url=cloud.image(path);return url?`<img class="member-avatar" src="${esc(url)}" alt="${esc(name)}的头像" loading="lazy">`:`<span class="member-avatar initial-avatar" aria-hidden="true">${esc((name||'食').slice(0,1))}</span>`;}
async function task(button,fn,target='#social-status'){const text=button?.textContent;if(button){button.disabled=true;button.textContent='处理中…';}try{await fn();}catch(e){$(target).textContent=e.message;$(target).hidden=false;}finally{if(button){button.disabled=false;if(button.textContent==='处理中…')button.textContent=text;}}}
function signedIn(){if(!cloud.user){location.hash='account';$('#auth-status').textContent='登录后即可分享成品、点赞和评论。';return false;}return true;}
function renderFeed(){const root=$('#community-feed');root.innerHTML=feed.length?feed.map(p=>`<article class="community-card"><button class="post-photo" data-post="${esc(p.id)}" aria-label="查看${esc(p.title)}"><img src="${esc(cloud.image(p.image_path))}" alt="${esc(p.title)}的用户实做成品" loading="lazy"><span>用户实做</span></button><div class="post-content"><div class="post-author">${avatar(p.avatar_path,p.username)}<span><strong>${esc(p.username)}</strong><small>${date(p.created_at)}</small></span></div><button class="post-title" data-post="${esc(p.id)}">${esc(p.title)}</button><p>${esc(p.body)}</p><button class="recipe-pill" data-source="${esc(p.recipe_id)}">按照「${esc(p.recipe_name)}」做的 ↗</button><div class="post-actions"><button data-like="${esc(p.id)}" aria-pressed="${p.liked}" ${p.author_id===cloud.user?.id?'disabled title="不能给自己的作品点赞"':''}>${p.liked?'♥':'♡'} <span>${p.like_count}</span> 点赞</button><button data-post="${esc(p.id)}">◌ ${p.comment_count} 评论</button>${p.author_id===cloud.user?.id?`<button data-withdraw="${esc(p.id)}">撤下</button>`:''}</div></div></article>`).join(''):`<div class="community-empty"><span>✳</span><h3>${cloud.ready?'第一份作品，等你来分享。':'每一顿认真做的饭，都值得被看见。'}</h3><p>${cloud.ready?'按照菜谱做完后，上传成品和心得。':'社区即将开放。账户开通后，即可分享成品、点赞和交流做饭心得。'}</p><a class="button ghost" href="#plan">先去寻找做饭灵感 ↗</a></div>`;$('#load-posts').hidden=feed.length===0||feed.length%12!==0;
root.querySelectorAll('[data-post]').forEach(b=>b.onclick=()=>openPost(feed.find(p=>p.id===b.dataset.post)));
root.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>window.ChiLeMe.openRecipe(b.dataset.source));
root.querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>{if(!signedIn())return;task(b,async()=>{await cloud.like(b.dataset.like);await loadFeed();});});
root.querySelectorAll('[data-withdraw]').forEach(b=>b.onclick=()=>task(b,async()=>{await cloud.withdraw(b.dataset.withdraw);await loadFeed();notice('作品已撤下，不再公开展示。');}));}
function renderLeaders(){const root=$('#creator-list');root.innerHTML=leaders.length?leaders.map((x,i)=>`<li><span class="rank-number">${String(i+1).padStart(2,'0')}</span>${avatar(x.avatar_path,x.username)}<div><strong>${esc(x.username)}</strong><small>${x.like_count} 赞 · ${x.comment_count} 位评论者 · ${x.post_count} 份作品</small></div></li>`).join(''):'<li class="leader-empty">真实作品产生后，榜单将在这里更新。</li>';}
async function loadFeed(append=false){if(window.ChiLeMeSocialV2?.active)return;if(!cloud.ready){renderFeed();renderLeaders();return;}if(loading)return;loading=true;try{if(!append)offset=0;const rows=await cloud.feed(sort,offset);feed=append?[...feed,...rows]:rows;renderFeed();leaders=await cloud.leaders($('#leader-sort').value);renderLeaders();notice('');}catch(e){notice(e.message);}finally{loading=false;}}
async function openPost(p){if(!p)return;activePost=p;$('#post-dialog-title').textContent=p.title;$('#post-dialog-detail').innerHTML=`<img class="post-detail-photo" src="${esc(cloud.image(p.image_path))}" alt="${esc(p.title)}"><div class="post-author">${avatar(p.avatar_path,p.username)}<strong>${esc(p.username)}</strong><small>${date(p.created_at)}</small></div><p class="post-full-body">${esc(p.body)}</p><button class="button ghost" id="post-source">查看「${esc(p.recipe_name)}」教程 ↗</button>`;$('#post-source').onclick=()=>{closeDialog($('#post-dialog'));window.ChiLeMe.openRecipe(p.recipe_id);};$('#comment-status').textContent='';$('#comment-body').value='';$('#post-dialog').showModal();await readComments();}
async function readComments(){if(!activePost)return;try{const comments=await cloud.comments(activePost.id);$('#post-comments').innerHTML=comments.length?comments.map(c=>`<li>${avatar(c.avatar_path,c.username)}<div><strong>${esc(c.username)}</strong><p>${esc(c.body)}</p><small>${date(c.created_at)}</small></div></li>`).join(''):'<li class="leader-empty">还没有评论，聊聊你的做饭心得吧。</li>';}catch(e){$('#comment-status').textContent=e.message;}}
function closeDialog(d){d.close();}
document.querySelectorAll('[data-close-social]').forEach(b=>b.onclick=()=>closeDialog(b.closest('dialog')));
$('#comment-form').onsubmit=e=>{e.preventDefault();if(!cloud.user){closeDialog($('#post-dialog'));signedIn();return;}const body=$('#comment-body').value.trim();if(!body)return;task(e.submitter,async()=>{await cloud.comment(activePost.id,body);$('#comment-body').value='';await readComments();await loadFeed();},'#comment-status');};
$('#community-sort').onchange=e=>{sort=e.target.value;loadFeed();};
$('#leader-sort').onchange=async e=>{if(!cloud.ready)return;try{leaders=await cloud.leaders(e.target.value);renderLeaders();}catch(error){notice(error.message);}};
$('#load-posts').onclick=e=>{offset=feed.length;task(e.target,()=>loadFeed(true));};
$('#refresh-community').onclick=()=>loadFeed();
$('#publish-post').onclick=()=>{if(!signedIn())return;$('#publish-status').textContent='';$('#publish-dialog').showModal();};
$('#post-recipe').innerHTML='<option value="">选择你跟做的菜谱</option>'+window.recipeBook.map(r=>`<option value="${esc(r.id)}">${esc(r.name)} · ${esc(r.category)}</option>`).join('');
$('#post-image').onchange=e=>{if(previewURL)URL.revokeObjectURL(previewURL);const file=e.target.files[0];$('#post-image-preview').hidden=!file;if(file){previewURL=URL.createObjectURL(file);$('#post-image-preview').src=previewURL;}};
$('#publish-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const file=$('#post-image').files[0];if(!file)throw new Error('请上传你实际做出的成品图。');const recipe_id=$('#post-recipe').value;if(!window.recipeBook.some(r=>r.id===recipe_id))throw new Error('请先选择跟做的菜谱。');const title=$('#post-title').value.trim(),body=$('#post-body').value.trim();if(title.length<2||!body)throw new Error('请填写作品标题和做饭心得。');const image_path=await cloud.upload(file,'dish');await cloud.post({recipe_id,title,body,image_path,minutes:Number($('#post-minutes').value)||null});e.target.reset();$('#post-image-preview').hidden=true;if(previewURL)URL.revokeObjectURL(previewURL);closeDialog($('#publish-dialog'));await loadFeed();notice('你的实做作品已发布，所有用户都可以查看。');},'#publish-status');};
$('#creator-apply').onclick=async()=>{if(!signedIn())return;try{const application=await cloud.application();if(application){notice('你的申请状态：'+({pending:'等待团队审核',invited:'已获邀请',declined:'暂未通过'}[application.status]||application.status));return;}const [likes,comments]=await Promise.all([cloud.leaders('likes'),cloud.leaders('comments')]);if(![...likes,...comments].some(x=>x.user_id===cloud.user.id)){notice('进入点赞榜或讨论榜前 10 名后，就可以申请参与新菜单共创。');return;}$('#apply-dialog').showModal();}catch(e){notice(e.message);}};
$('#apply-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await cloud.apply($('#apply-message').value.trim());closeDialog($('#apply-dialog'));notice('共创申请已提交。团队审核后会更新申请状态。');},'#apply-status');};
function clearPendingVerification(){verificationEmail='';pendingPassword='';pendingUsername='';try{sessionStorage.removeItem('chileme-pending-email');}catch{}}
function authView(mode){authMode=mode;$('#register-name-row').hidden=mode!=='signup';$('#auth-password-row').hidden=mode==='verify';$('#auth-code-row').hidden=mode!=='verify';$('#auth-password').required=mode!=='verify';$('#auth-username').required=mode==='signup';$('#auth-code').required=mode==='verify';$('#auth-email').readOnly=mode==='verify';$('#auth-email').value=mode==='verify'?verificationEmail:$('#auth-email').value;$('#auth-password').autocomplete=mode==='signup'?'new-password':'current-password';$('#auth-password').minLength=mode==='signup'?8:1;$('#auth-submit').textContent={login:'登录，继续我的厨房日常',signup:'注册并发送验证邮件',verify:'验证邮箱并登录'}[mode];$('#resend-code').hidden=mode!=='verify';$('#auth-heading').textContent={login:'欢迎回到你的厨房。',signup:'从今天起，好好吃饭。',verify:'验证邮箱，开始分享。'}[mode];document.querySelectorAll('[data-auth-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.authMode===mode)));$('#auth-status').textContent=cloud.registrationEnabled?'':'邮箱注册正在开通中，暂时不能发送验证码。做饭功能可继续免费使用。';}
document.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>{const mode=b.dataset.authMode;if(mode==='verify'){verificationEmail=$('#auth-email').value.trim();if(!$('#auth-email').checkValidity()||!verificationEmail){$('#auth-status').textContent='先填写注册邮箱，再输入验证码。';return;}}else if(authMode==='verify'){clearPendingVerification();$('#auth-code').value='';}authView(mode);});
$('#auth-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const email=$('#auth-email').value.trim(),password=$('#auth-password').value;if(authMode==='signup'){const name=$('#auth-username').value.trim();if(name.length<2)throw new Error('用户名至少 2 个字符。');await cloud.signup(email,password,name);verificationEmail=email;pendingPassword=password;pendingUsername=name;try{sessionStorage.setItem('chileme-pending-email',email);}catch{}$('#auth-password').value='';authView('verify');$('#auth-status').textContent='验证邮件已发送。请打开邮件中的验证链接；若邮件提供 8 位验证码，也可在这里填写。';}else if(authMode==='verify'){await cloud.verify(verificationEmail,$('#auth-code').value.trim());if(pendingPassword){const chosenPassword=pendingPassword;pendingPassword='';await cloud.setPassword(chosenPassword);}if(pendingUsername){await cloud.updateProfile(pendingUsername,'',null);pendingUsername='';}clearPendingVerification();$('#auth-code').value='';location.hash='ingredients';}else{await cloud.login(email,password);$('#auth-password').value='';location.hash='ingredients';}},'#auth-status');};
$('#resend-code').onclick=e=>task(e.target,async()=>{await cloud.resend(verificationEmail);$('#auth-status').textContent='验证邮件已重新发送。请打开最新的验证链接，或填写最新验证码。';},'#auth-status');
$('#password-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const password=$('#account-new-password').value;if(password!==$('#account-confirm-password').value)throw new Error('两次输入的密码不一致。');await cloud.setPassword(password);e.target.reset();$('#password-status').textContent='登录密码已保存，以后可用邮箱＋密码登录。';},'#password-status');};
$('#logout').onclick=e=>task(e.target,()=>cloud.logout(),'#profile-status');
$('#profile-avatar').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){e.target.value='';$('#profile-status').textContent='请选择 JPG、PNG 或 WebP 图片，大小不超过 5 MB。';return;}if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(file);$('#profile-avatar-display').innerHTML=`<img class="member-avatar" src="${esc(previewURL)}" alt="待保存的新头像预览">`;$('#profile-status').textContent='新头像已预览，点击“保存个人主页”后发布到你的资料。';};
$('#profile-form').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{const username=$('#profile-name').value.trim();if(username.length<2)throw new Error('用户名至少 2 个字符。');const file=$('#profile-avatar').files[0],path=file?await cloud.upload(file,'avatar'):null;await cloud.updateProfile(username,$('#profile-bio').value.trim(),path);$('#profile-avatar').value='';if(previewURL){URL.revokeObjectURL(previewURL);previewURL='';}await updateAccount();await loadFeed();$('#profile-status').textContent='个人主页已保存，头像会同步显示在社区中。';},'#profile-status');};
async function updateAccount(){const user=cloud.user;$('#account-link').textContent=user?'我的账户':'登录 / 注册';$('#auth-panel').hidden=!!user;$('#profile-panel').hidden=!user;if(!user){profile=null;return;}try{profile=await cloud.profile();if(!profile)throw new Error('个人资料尚未准备好，请稍后刷新后再试。');$('#profile-name').value=profile.username;$('#profile-bio').value=profile.bio;$('#profile-display-name').textContent=profile.username;$('#profile-bio-display').textContent=profile.bio||'写一句话，让饭友认识你。';$('#profile-avatar-display').innerHTML=avatar(profile.avatar_path,profile.username);$('#profile-email').textContent=user.email+' · 邮箱已验证';}catch(e){$('#profile-status').textContent=e.message;}}
window.addEventListener('chileme:auth',()=>{updateAccount();loadFeed();});
window.addEventListener('hashchange',()=>{if(location.hash==='#community')loadFeed();if(location.hash==='#account')updateAccount();});
document.querySelectorAll('[data-member-interest]').forEach(b=>b.onclick=()=>{$('#membership-status').textContent='会员服务尚未开通，目前全部做饭功能免费使用。价格确认并接入支付后才会开放购买。';});
authView('login');try{const pending=sessionStorage.getItem('chileme-pending-email');if(pending){verificationEmail=pending;authView('verify');}}catch{}if(!cloud.ready){$('#auth-status').textContent='账户服务筹备中，暂未开放注册。做饭功能可继续免费使用。';$('#cloud-notice').hidden=false;}else{$('#cloud-notice').hidden=cloud.registrationEnabled;if(!cloud.registrationEnabled)$('#cloud-notice').textContent='社区已连接，正在开通邮箱注册。完成后就可以分享实做作品、点赞与评论。';cloud.restore().then(updateAccount).catch(e=>{$('#auth-status').textContent=e.message;});}updateAccount();renderFeed();renderLeaders();if(location.hash==='#community')loadFeed();
})();
